{"implementation":"def solve(case):
    nodes = case['nodes']
    required_symbols = set(case['required_symbols'])
    node_map = {node['id']: node for node in nodes}
    children = {node['id']: [] for node in nodes}
    for node in nodes:
        parent = node.get('parent')
        if parent is not None:
            children[parent].append(node['id'])
    non_removable_ids = {node['id'] for node in nodes if not node['removable']}
    covered_symbols = set()
    for nid in non_removable_ids:
        covered_symbols.add(node_map[nid]['symbol'])
    removable_nodes = [node for node in nodes if node['removable']]
    removable_nodes_sorted = sorted(removable_nodes, key=lambda x: -x['utility'])
    keep_ids = set(non_removable_ids)
    missing_symbols = required_symbols - covered_symbols
    for sym in missing_symbols:
        for node in removable_nodes_sorted:
            if node['symbol'] == sym and node['id'] not in keep_ids:
                keep_ids.add(node['id'])
                covered_symbols.add(sym)
                break
    removed_node_ids = [node['id'] for node in removable_nodes if node['id'] not in keep_ids]
    retained_node_ids = [node['id'] for node in nodes if node['id'] not in removed_node_ids]
    return {
        'removed_node_ids': removed_node_ids,
        'retained_node_ids': retained_node_ids
    }"}
